#include <iostream>
#include <utility>
#include <string>

class User {
public:
    User(int id, std::string name) : id_(id), name_(std::move(name)) {}
    void print() const { std::cout << id_ << ':' << name_ << '\n'; }
private:
    int id_;
    std::string name_;
};
int main() { User user{7, "Ari"}; user.print(); }
